/*
 * A183170  First of two trees generated by the Beatty sequence of sqrt(2).
 * https://oeis.org/A183170
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   not stated
 * Range:     u8 n <= 3, u16 n <= 15, u32 n <= 163, u64 n <= 8192,
 *            u128 n <= 8192, big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  A183170 – First tree generated by the Beatty sequence of sqrt(2)
 *  Each node v has children:
 *      L(v) = floor(v*sqrt(2))
 *      U(v) = floor(v*(2+sqrt(2)))  = L(v) + 2*v
 *  The left child is omitted when L(v) == v to avoid a self‑loop.
 *  The tree starts from root 1.  This function returns the n‑th
 *  term (1‑based) of the breadth–first traversal.
 *
 *  Complexity:  O(n) time and O(n) memory for the first n terms.
 */

#include <stdlib.h>
#include <stdbool.h>
#include "../utils/floor_sqrt.h"

static seq_t   *seq_cache = NULL;   /* sequence values              */
static idx_t    seq_len   = 0;        /* number of stored terms       */
static size_t   seq_cap   = 0;        /* allocation capacity          */

static seq_t   *queue     = NULL;   /* BFS queue                   */
static idx_t    q_head    = 0;       /* next element to pop          */
static idx_t    q_tail    = 0;       /* next free slot               */
static size_t   q_cap     = 0;       /* queue capacity               */

/* Ensure seq_cache has at least 'needed' slots */
static void
ensure_seq_capacity(size_t needed)
{
    if (seq_cap >= needed) return;
    size_t new_cap = seq_cap ? seq_cap * 2 : 64;
    while (new_cap < needed) new_cap *= 2;
    seq_t *tmp = (seq_t *)realloc(seq_cache, new_cap * sizeof(seq_t));
    if (!tmp) abort();
    seq_cache = tmp;
    seq_cap   = new_cap;
}

/* Ensure queue has at least 'needed' slots */
static void
ensure_queue_capacity(size_t needed)
{
    if (q_cap >= needed) return;
    size_t new_cap = q_cap ? q_cap * 2 : 64;
    while (new_cap < needed) new_cap *= 2;
    seq_t *tmp = (seq_t *)realloc(queue, new_cap * sizeof(seq_t));
    if (!tmp) abort();
    queue   = tmp;
    q_cap   = new_cap;
}

seq_t a(idx_t n)
{
    if (n == 0) return 0; /* undefined for 0, but safe */

    /* initialise structures on first call */
    if (seq_cache == NULL) {
        ensure_seq_capacity(64);
        ensure_queue_capacity(64);
        queue[q_tail++] = (seq_t)1;           /* root node */
    }

    /* generate terms until we have at least n of them */
    while (seq_len < n) {
        /* pop next node from the queue */
        seq_t cur = queue[q_head++];

        /* store the value in the sequence cache */
        if (seq_len == seq_cap) {
            ensure_seq_capacity(seq_len + 1);
        }
        seq_cache[seq_len++] = cur;

        /* compute left child L = floor(v*sqrt(2)) = floor_sqrt(2*v*v) */
        seq_t L = floor_sqrt((seq_t)2 * cur * cur);

        /* push left child if it is not the same as the parent */
        if (L != cur) {
            if (q_tail == q_cap) {
                ensure_queue_capacity(q_tail + 1);
            }
            queue[q_tail++] = L;
        }

        /* compute right child U = L + 2*v */
        seq_t U = L + (seq_t)2 * cur;
        if (q_tail == q_cap) {
            ensure_queue_capacity(q_tail + 1);
        }
        queue[q_tail++] = U;
    }

    return seq_cache[n - 1];
}
